import {VariantLibraryView} from '../../src/features/variant-library.ts';import {Repository} from '../../src/domain/repository.ts';import {defaultReportSettings} from '../../src/domain/reports.ts';import {appendCustomVariant} from '../../src/domain/variant-edits.ts';
export async function createLibraryFixture(){const data=new Map<string,string>(),repo=new Repository({read:async k=>data.get(k)??null,write:async(k,v)=>{data.set(k,v)},remove:async k=>{data.delete(k)}}),exp='abcdef123456',other='123456abcdef',original='原式 $x=1$ %%DATA:v%%';let confirm=false,uses=0,exported=0,exportedData:string='',imports=0,compatible=true,fail=false,pending=false,late:(()=>void)|undefined,completed=0;for(let i=0;i<24;i++)await repo.archiveVariant({experimentId:exp,section:'原理',index:0,original,text:(i===0?'<img src=x onerror=alert(1)>':'归档 '+i+' ')+original});await repo.archiveVariant({experimentId:other,section:'原理',index:0,original,text:'另一实验 '+original});const view=new VariantLibraryView([{id:exp,name:'实验一'},{id:other,name:'实验二'}],{list:async id=>{if(pending)await new Promise<void>(r=>late=r);if(fail)throw Error('模拟目录读取失败');const rows=await repo.listVariantLibrary(id);completed++;return rows;},read:(id,key)=>repo.readVariantArchive(id,key),remove:(id,key)=>repo.removeVariantArchive(id,key),clear:id=>repo.clearVariantLibrary(id,async()=>{for(const key of [...data.keys()])if(key.startsWith('variant-library-'+id+'-')||key.startsWith('variant-entry-'+id+'-'))data.delete(key);}),compatible:()=>compatible,use:async entry=>{uses++;await repo.saveReportSettings(entry.experimentId,appendCustomVariant(await repo.loadReportSettings(entry.experimentId),{原理:[original]},entry.section,{id:entry.id,baseIndex:entry.index,original:entry.original,text:entry.text}));},export:async entries=>{exported=entries.length;exportedData=JSON.stringify({type:'lab-maker-variant-library',version:1,entries});},import:async entries=>{imports++;for(const entry of entries)await repo.archiveVariant(entry);return {imported:entries.length,total:entries.length};},confirm:async()=>confirm});const mount=()=>view.mount(document.querySelector<HTMLElement>('#library-host')!);mount();return {state:()=>({uses,exported,imports,completed,busy:view.isSaving}),file:()=>exportedData,confirm:(v:boolean)=>confirm=v,compatible:(v:boolean)=>compatible=v,fail:(v:boolean)=>fail=v,pending:()=>pending=true,late:()=>{pending=false;late?.();},leave:()=>view.leave(),reopen:mount,adopted:()=>repo.loadReportSettings(exp),count:async id=>(await repo.listVariantLibrary(id??exp)).length};}
